function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0].toUpperCase() }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=^*/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

const FAIL = new Error('parse')

// Returns an AST, or null when the grammar rejects the body.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v

  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw FAIL
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v !== '(') throw FAIL
      p++
      const e = cmp()
      if (!isOp(')')) throw FAIL
      p++
      return { k: 'paren', e }
    }
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw FAIL
        }
      }
      return { k: 'call', name: t.v, args }
    }
    if (isOp(':')) {
      p++
      const t2 = toks[p]
      if (!t2 || t2.t !== 'word') throw FAIL
      p++
      return { k: 'range', from: parseAddress(t.v), to: parseAddress(t2.v) }
    }
    if (t.v === 'TRUE') return { k: 'bool', v: true }
    if (t.v === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', addr: parseAddress(t.v) }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
"}

