{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { addrName } from './addr.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ZERO = num(0)
const ARITY = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

// Whether the tree breaks a static rule (misplaced range, wrong argument count).
function invalid(n, direct = false) {
  switch (n.k) {
    case 'range': return !direct
    case 'paren': case 'un': return invalid(n.e)
    case 'bin': return invalid(n.l) || invalid(n.r)
    case 'call': {
      const ar = ARITY[n.name]
      if (ar && (n.args.length < ar[0] || n.args.length > ar[1])) return true
      const single = n.name === 'ABS' || n.name === 'IF'
      return n.args.some((a) => invalid(a, !single && (!ar || true)))
    }
    default: return false
  }
}

function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  format(v) {
    if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
    if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
    return String(v.v)
  }

  valueOf(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    const v = this.compute(cell.content)
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(c) {
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      if (!ast || invalid(ast)) return err('#ERR!')
      return this.ev(ast)
    }
    if (c === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
    if (ERRORS.includes(c)) return err(c)
    return { t: 's', v: c }
  }

  fin(x) {
    return Number.isFinite(x) ? num(x) : err('#DIV/0!')
  }

  toNum(v) {
    if (v.t === 'e') return v
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }

  ref(a) {
    return a ? this.valueOf(addrName(a)) : err('#REF!')
  }

  // Values an argument contributes.
  argValues(n) {
    if (n.k === 'range') {
      if (!n.from || !n.to) return [err('#REF!')]
      const out = []
      const c1 = Math.min(n.from.col, n.to.col), c2 = Math.max(n.from.col, n.to.col)
      const r1 = Math.min(n.from.row, n.to.row), r2 = Math.max(n.from.row, n.to.row)
      for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(this.valueOf(addrName({ col: c, row: r })))
      return out
    }
    return [this.ev(n)]
  }

  ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return this.ref(n.addr)
      case 'un': {
        const v = this.toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return this.fin(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (l.t === 'e') return l
      const r = this.ev(n.r)
      if (r.t === 'e') return r
      let d
      if (l.t !== r.t) d = rank[l.t] - rank[r.t]
